SELECT opened_cohort, city, sqft_count, min_sqft FROM (SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END opened_cohort, city, COUNT(sqft) sqft_count, MIN(sqft) min_sqft FROM stores WHERE sqft BETWEEN 12597 AND 14704 GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END, city) agg WHERE sqft_count < 6
